from __future__ import annotations

from sqlalchemy import CheckConstraint, String, Text
from sqlalchemy.orm import Mapped, mapped_column

from api.base import Base, TimestampMixin


class SiteSettings(TimestampMixin, Base):
    """Singleton: exactly one row, id = 1. There is no create or delete endpoint."""

    __tablename__ = "site_settings"
    __table_args__ = (CheckConstraint("id = 1", name="singleton"),)

    # autoincrement=False: the id is fixed, never generated by the database
    id: Mapped[int] = mapped_column(primary_key=True, autoincrement=False, default=1)

    company_name: Mapped[str] = mapped_column(String(160), default="Ideal Electric")
    tagline: Mapped[str | None] = mapped_column(String(200))
    about_short: Mapped[str | None] = mapped_column(Text)

    phone_primary: Mapped[str | None] = mapped_column(String(40))
    phone_secondary: Mapped[str | None] = mapped_column(String(40))
    email_sales: Mapped[str | None] = mapped_column(String(254))
    whatsapp_number: Mapped[str | None] = mapped_column(String(20))  # digits only, for wa.me links

    address_line: Mapped[str | None] = mapped_column(String(300))
    city: Mapped[str | None] = mapped_column(String(100))
    google_maps_url: Mapped[str | None] = mapped_column(String(500))
    business_hours: Mapped[str | None] = mapped_column(String(300))

    facebook_url: Mapped[str | None] = mapped_column(String(300))
    linkedin_url: Mapped[str | None] = mapped_column(String(300))
    instagram_url: Mapped[str | None] = mapped_column(String(300))

    default_meta_title: Mapped[str | None] = mapped_column(String(160))
    default_meta_description: Mapped[str | None] = mapped_column(String(320))

    is_placeholder: Mapped[bool] = mapped_column(default=True, server_default="true")